import {distribution,categoryColor,categoryAppearance,layerNames,UNKNOWN} from './layers.mjs';
export function createPlanFilters(ctx){
 const root=document.getElementById('planFilters'),button=document.getElementById('planSettingsOpen'),esc=ctx.esc;
 let opened=false,categoryQuery='';
 const normalized=value=>String(value).normalize('NFD').replace(/\p{Diacritic}/gu,'').toLocaleLowerCase('es');
 const families=[['walls','Muros'],['PAV','Pavimentos'],['CIE','Cielos'],['avance','Avance de obra'],['observaciones','Observaciones en terreno'],['asepsis','Asepsia'],['paint','Pinturas'],['sector','Sectores'],['status','Estado de revisión']];
 const origin=a=>a.kind==='source'?'Leyenda ARQ-CIE':a.kind==='custom'?'Personalizado':'Paleta de consulta';
 // Filtros y capas en un solo panel: especialidad del plano, capas del dibujo y textos sobre el plano. Las especialidades
 // siguen en su barra (disciplines.mjs), que queda oculta en Arquitectura: aquí se pulsan sus mismos botones.
 const tiposPlano=()=>[...document.querySelectorAll('.planTypes [data-plan-type]')];
 const textosPlano=[['layerCodes','Códigos de recinto'],['layerNames','Nombres de recinto']];
 function seccionPlano(){const capas=ctx.capas?.()||[];return `<h3 class="filterSeccion">Especialidad</h3><div class="filterTiposPlano">${tiposPlano().map(b=>`<button type="button" data-tipo-plano="${esc(b.dataset.planType)}" aria-pressed="${b.getAttribute('aria-pressed')}" ${b.disabled?'disabled':''}>${esc(b.firstChild.textContent)}</button>`).join('')}</div><h3 class="filterSeccion">Capas</h3><div class="filterCapas">${capas.map(c=>`<label class="check"><input type="checkbox" data-capa="${esc(c.id)}" ${c.visible?'checked':''}> ${esc(c.nombre)}</label>`).join('')}${textosPlano.map(([id,nombre])=>`<label class="check"><input type="checkbox" data-texto-plano="${id}" ${document.getElementById(id)?.checked?'checked':''}> ${nombre}</label>`).join('')}</div>${capas.length?'':'<small class="filterHelp">Este plano viene de PDF sin capas: mobiliario, ejes y relleno se podrán apagar cuando se carguen sus láminas DWG.</small>'}<h3 class="filterSeccion">Filtros</h3>`;}
 function close(focus=false){if(!opened)return;opened=false;root.hidden=true;document.body.classList.remove('filtersOpen');button.setAttribute('aria-expanded','false');if(focus)button.focus();ctx.resize();}
 function open(){if(ctx.editing())return ctx.toast('Guarda o cancela el contorno antes de abrir los filtros.');ctx.enter();opened=true;root.hidden=false;document.body.classList.add('filtersOpen');document.body.classList.add('hideRight','hideLeft');button.setAttribute('aria-expanded','true');render();ctx.resize();root.querySelector('#planFilterSearch').focus({preventScroll:true});}
 function update(){if(!opened)return;root.querySelector('#planFilterCount').textContent=ctx.rows().length+' de '+ctx.all().length+' recintos';const input=root.querySelector('#planFilterSearch');if(document.activeElement!==input)input.value=ctx.query();}
 function render(){
  const focused=document.activeElement,focusId=root.contains(focused)?focused.id:null,focusKey=root.contains(focused)?focused.dataset.filter:null;
  const {active,filters,enabled,colors}=ctx.state(),scroll=root.querySelector('.planFilterBody')?.scrollTop||0;
  const note=active==='observaciones'?'Recintos según sus observaciones en terreno: con vencidas, abiertas, corregidas por verificar o cerradas (registros de este equipo).':active==='avance'?'Estado del recinto según el avance valorizado por partida (registros de este dispositivo).':active==='CIE'?'Colores cotejados con las ocho leyendas ARQ-CIE. Los colores personalizados sustituyen la fuente.':'Paleta de consulta al 32% de opacidad. La leyenda ARQ no asigna colores a estos códigos.';
  root.innerHTML=`<div class="planFilterHead"><div><span class="section-label">HERRAMIENTAS DEL PLANO</span><h2 id="planFiltersTitle">Filtros y capas</h2></div><button id="closePlanFilters" aria-label="Cerrar filtros y capas">×</button></div><div class="planFilterBody"><label for="planFilterSearch">Código, recinto o terminación</label><input id="planFilterSearch" type="search" placeholder="Buscar en este piso…" value="${esc(ctx.query())}" autocomplete="off"><p id="planFilterCount" role="status"></p>${seccionPlano()}<div class="filterChips">${Object.entries(filters).flatMap(([type,keys])=>keys.map(key=>`<button data-remove-type="${esc(type)}" data-remove-key="${esc(key)}" aria-label="Quitar filtro ${esc(ctx.label(type,key))}">${esc((layerNames[type]||type)+' '+key)}<span aria-hidden="true">×</span></button>`)).join('')}</div><label class="check filterPaint"><input id="paintEnabled" type="checkbox" ${enabled?'checked':''}> Mostrar colores en el plano</label><label for="activeLayer">Colorear y buscar por</label><select id="activeLayer">${families.map(([key,name])=>`<option value="${key}" ${key===active?'selected':''}>${name}</option>`).join('')}</select><div class="filterCategoryHead"><h3>${esc(layerNames[active])}</h3><div><button id="toggleCategorySearch" aria-controls="filterCategorySearch" aria-expanded="${!!categoryQuery}">Buscar</button><button id="clearCategory">Quitar filtro</button></div></div><input id="filterCategorySearch" type="search" aria-label="Buscar categoría" placeholder="Código o descripción…" value="${esc(categoryQuery)}" ${categoryQuery?'':'hidden'}><div id="filterCategoryList">${distribution(ctx.all(),active).map(([key,n])=>`<div class="categoryControl" data-category-text="${esc(normalized(ctx.label(active,key)))}"><label><input type="checkbox" data-filter="${esc(key)}" ${(filters[active]||[]).includes(key)?'checked':''}><span>${esc(ctx.label(active,key))}<small class="colorOrigin">${origin(categoryAppearance(active,key,colors))}</small></span><b title="Recintos de este piso con esta categoría">${n}</b></label><input type="color" aria-label="Color de ${esc(ctx.label(active,key))}" data-color="${esc(key)}" value="${categoryColor(active,key,colors)}"></div>`).join('')}</div><p id="noFilterCategories" hidden>Sin categorías coincidentes.</p><small class="filterHelp">Los números de cada categoría corresponden al piso completo. En una familia se suman; entre familias se intersectan.</small><details class="filterMore" ${filters.asepsis?.length||filters.status?.length||filters.sector?.length?'open':''}><summary>Más filtros</summary><label for="asepsisAttribute">Asepsia documentada</label><select id="asepsisAttribute"><option value="">Todas / sin filtro</option>${distribution(ctx.all(),'asepsis').map(([key,n])=>`<option value="${esc(key)}" ${(filters.asepsis||[]).includes(key)?'selected':''}>${esc(key===UNKNOWN?'Clasificación no determinada':'Asepsia '+key)} · ${n}</option>`).join('')}</select>${[['status','Estado de revisión'],['sector','Sector']].map(([key,name])=>`<label for="filter-${key}">${name}</label><select id="filter-${key}" data-extra-filter="${key}"><option value="">Todos / sin filtro</option>${distribution(ctx.all(),key).map(([value,n])=>`<option value="${esc(value)}" ${(filters[key]||[]).includes(value)?'selected':''}>${esc(key==='sector'?'Sector '+value:value)} · ${n}</option>`).join('')}</select>`).join('')}</details><details class="filterMore"><summary>Colores y respaldo</summary><p id="layerColorNote">${note}</p><button id="resetLayerColors">Restablecer colores de esta capa</button><button id="filterBackup">Respaldar correcciones</button></details><p class="filterHelp">Los colores representan atributos documentados o estados registrados. No certifican ejecución ni superficies.</p></div><div class="planFilterFooter"><button id="clearPlanFilters">Limpiar todo</button><button id="applyPlanFilters" class="primary">Ver en el plano</button></div>`;
  root.querySelector('#closePlanFilters').onclick=()=>close(true);root.querySelector('#applyPlanFilters').onclick=()=>close(true);
  root.querySelectorAll('[data-tipo-plano]').forEach(b=>b.onclick=()=>{const tipo=b.dataset.tipoPlano,destino=tiposPlano().find(x=>x.dataset.planType===tipo),sale=!['architecture','walls'].includes(tipo);if(sale)close();destino?.click();if(!sale)setTimeout(render,60);});
  root.querySelectorAll('[data-capa]').forEach(i=>i.onchange=()=>ctx.mostrarCapa?.(i.dataset.capa,i.checked));
  root.querySelectorAll('[data-texto-plano]').forEach(i=>i.onchange=()=>{const original=document.getElementById(i.dataset.textoPlano);original.checked=i.checked;original.dispatchEvent(new Event('change'));});
  root.querySelector('#planFilterSearch').oninput=e=>ctx.search(e.target.value);
  root.querySelector('#paintEnabled').onchange=e=>ctx.change({enabled:e.target.checked},false);
  root.querySelector('#activeLayer').onchange=e=>{categoryQuery='';ctx.change({active:e.target.value,enabled:true});render();};
  root.querySelector('#toggleCategorySearch').onclick=()=>{const input=root.querySelector('#filterCategorySearch');input.hidden=!input.hidden;root.querySelector('#toggleCategorySearch').setAttribute('aria-expanded',String(!input.hidden));if(!input.hidden)input.focus();else{categoryQuery='';input.value='';searchCategories();}};
  root.querySelector('#filterCategorySearch').oninput=e=>{categoryQuery=e.target.value;searchCategories();};
  root.querySelectorAll('[data-filter]').forEach(input=>input.onchange=()=>{const chosen=[...root.querySelectorAll('[data-filter]:checked')].map(n=>n.dataset.filter);ctx.filter(active,chosen);render();});
  root.querySelectorAll('[data-remove-type]').forEach(b=>b.onclick=()=>{ctx.filter(b.dataset.removeType,(ctx.state().filters[b.dataset.removeType]||[]).filter(k=>k!==b.dataset.removeKey));render();});
  root.querySelector('#clearCategory').onclick=()=>{ctx.filter(active,[]);render();};
  root.querySelector('#asepsisAttribute').onchange=e=>{ctx.filter('asepsis',e.target.value?[e.target.value]:[]);render();};
  root.querySelectorAll('[data-extra-filter]').forEach(input=>input.onchange=()=>{ctx.filter(input.dataset.extraFilter,input.value?[input.value]:[]);render();});
  root.querySelectorAll('[data-color]').forEach(input=>input.oninput=()=>{ctx.color(active,input.dataset.color,input.value);input.closest('.categoryControl').querySelector('.colorOrigin').textContent='Personalizado';});
  root.querySelector('#resetLayerColors').onclick=()=>{ctx.resetColors(active);render();};
  root.querySelector('#clearPlanFilters').onclick=()=>{categoryQuery='';ctx.reset();render();};root.querySelector('#filterBackup').onclick=()=>document.getElementById('import').click();
  root.querySelector('.planFilterBody').scrollTop=scroll;searchCategories();update();const next=focusKey?[...root.querySelectorAll('[data-filter]')].find(input=>input.dataset.filter===focusKey):focusId?[...root.querySelectorAll('[id]')].find(node=>node.id===focusId):null;next?.focus({preventScroll:true});
 }
 function searchCategories(){const query=normalized(categoryQuery.trim());let n=0;root.querySelectorAll('[data-category-text]').forEach(row=>{row.hidden=!row.dataset.categoryText.includes(query);if(!row.hidden)n++;});root.querySelector('#noFilterCategories').hidden=!!n;}
 button.onclick=()=>opened?close(true):open();
 root.addEventListener('keydown',event=>{if(event.key==='Escape'){event.stopPropagation();close(true);}});
 window.addEventListener('atlas-floor-home',()=>close());
 return {open,close,update,isOpen:()=>opened};
}
